//! 生成 Tauri 的 ACL 与能力清单。
//!
//! 应用命令在这里登记，`permissions/autogenerated/` 里的 `allow-*` 才能被
//! `capabilities/default.json` 引用；未登记的命令在 IPC 层被拒绝。

fn main() {
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(
        tauri_build::AppManifest::new().commands(&[
            "app_info",
            "profiles_list",
            "profiles_get",
            "profiles_create",
            "profiles_update",
            "kernel_install",
            "runtime_start",
            "runtime_stop",
            "runtime_status",
        ]),
    ))
    .expect("tauri build 失败");
}
